 public void TestVectorControls(){SetDocument(new Document("A4",100),null);AddTypedLayer(true);canvas.Zoom=1;canvas.Offset=PointF.Empty;vectorMode.SelectedItem="Polygon";polygonSides.Value=6;canvas.TestDrag(new Point(200,200),new Point(300,200));var shape=canvas.Doc.Selected.Vectors[0];if(shape.Points.Count!=6)throw new Exception("Polygon side count");foreach(var point in shape.Points)if(Math.Abs(StrokeSession.Distance(point,new PointF(200,200))-100)>.01)throw new Exception("Regular polygon radius");vectorPicker.PerformClick();canvas.TestVisibleVectorCursor();int history=undo.Count;canvas.TestDrag(new Point(300,200),new Point(300,200));if(undo.Count!=history)throw new Exception("Picking alone must not create undo snapshots");vectorWidth.Value=12;if(shape.Width!=12)throw new Exception("Stroke weight field updates selected shape");polygonSides.Value=8;if(shape.Points.Count!=8)throw new Exception("Side field updates selected polygon");if(undo.Any(item=>item.Layer.IsVector&&item.Pixels!=null))throw new Exception("Vector undo must not copy raster canvas");Travel(undo,redo);if(canvas.Doc.Selected.Vectors[0].Points.Count!=6)throw new Exception("Undo polygon sides");Travel(undo,redo);if(canvas.Doc.Selected.Vectors[0].Width==12)throw new Exception("Undo stroke weight");
  var layer=canvas.Doc.Selected;shape=layer.Vectors[0];layer.Rendered();var before=shape.Bounds();for(int i=0;i<shape.Points.Count;i++)shape.Points[i]=new PointF(shape.Points[i].X+7,shape.Points[i].Y+3);layer.UpdateVectorRegion(RectangleF.Union(before,shape.Bounds()));byte[] partial=Document.Png(layer.Rendered());layer.InvalidateVectors();byte[] full=Document.Png(layer.Rendered());if(polygonSides.Minimum!=3||polygonSides.Maximum!=24)throw new Exception("Polygon limits");canvas.TestDrag(Point.Round(shape.Points[0]),Point.Round(shape.Points[0]));polygonSides.Value=24;if(canvas.Doc.Selected.Vectors[0].Points.Count!=24)throw new Exception("24-sided polygon");polygonSides.Value=3;if(canvas.Doc.Selected.Vectors[0].Points.Count!=3)throw new Exception("3-sided polygon");if(!partial.SequenceEqual(full))throw new Exception("Partial redraw must match full render");dirty=false;
 }
